import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        p = []
        for _ in range(n):
            p.append(int(next(iterator)))
    except StopIteration:
        return

    grid = [[0] * (i + 1) for i in range(n)]

    for r in range(n):
        val = p[r]
        grid[r][r] = val
        remaining = val - 1

        c = r
        while remaining > 0:
            c -= 1
            if c < 0:
                break
            if grid[r][c] != 0:
                break
            grid[r][c] = val
            remaining -= 1

        if remaining > 0:
            print("-1")
            return

    for r in range(n):
        print(*(grid[r]))

if __name__ == "__main__":
    solve()
